// The 8:30 cut plays the 6:23 desk world on a remapped clock (see remap-data.ts, generated by
// continuous-cut/build_remap.py): out time -> world time, piecewise linear between word anchors.
import { ANCHORS } from "./remap-data";

const interp = (x: number, from: 0 | 1) => {
  const to = 1 - from;
  const a = ANCHORS;
  if (x <= a[0][from]) return a[0][to] + (x - a[0][from]);
  const last = a[a.length - 1];
  if (x >= last[from]) return last[to] + (x - last[from]);
  let lo = 0;
  let hi = a.length - 1;
  while (hi - lo > 1) {
    const mid = (lo + hi) >> 1;
    if (a[mid][from] <= x) lo = mid;
    else hi = mid;
  }
  const u = (x - a[lo][from]) / (a[hi][from] - a[lo][from]);
  return a[lo][to] + (a[hi][to] - a[lo][to]) * u;
};

/** world seconds (world.ts timing) for an output second */
export const worldTime = (t: number) => interp(t, 0);
/** output second at which a world second plays */
export const outTime = (w: number) => interp(w, 1);
